VALUES
    (1, 'Внедрение CRM для сети аптек «ФармаПлюс»', 'Единая карточка клиента, история обращений и контроль взаимодействия с аптечными точками.', TIMESTAMP '2025-10-20 09:30:00', DATE '2025-11-03', DATE '2026-05-30'),
    (2, 'Мобильное приложение доставки «БыстроМаркет»', 'Приложение для выбора продуктов, оплаты заказа и отслеживания курьера.', TIMESTAMP '2025-11-10 09:30:00', DATE '2025-12-01', NULL),
    (3, 'Аналитическая платформа розничных продаж', 'Сбор чеков из кассовой системы и ERP для анализа выручки, среднего чека и маржинальности.', TIMESTAMP '2025-12-05 09:30:00', DATE '2026-01-12', DATE '2026-09-30'),
    (4, 'Личный кабинет корпоративных клиентов', 'Веб-кабинет для просмотра договоров, закрывающих документов и истории взаиморасчётов.', TIMESTAMP '2026-01-05 09:30:00', DATE '2026-01-26', NULL),
