    (6, 'Редизайн интернет-магазина «ДомМаркет»', 'Обновление каталога, карточки товара и сценария оформления заказа для мобильных устройств.', TIMESTAMP '2026-02-01 09:30:00', DATE '2026-02-16', DATE '2026-08-31'),
    (7, 'Портал заявок внутренней IT-поддержки', 'Регистрация обращений сотрудников, маршрутизация заявок и контроль сроков решения.', TIMESTAMP '2026-02-20 09:30:00', DATE '2026-03-09', DATE '2026-12-15'),
    (8, 'Корпоративная платформа обучения', 'Каталог учебных курсов, тестирование знаний и отслеживание прохождения обучения.', TIMESTAMP '2026-03-01 09:30:00', DATE '2026-03-23', NULL),
    (9, 'Автоматизация финансовой отчётности', 'Формирование управленческих отчётов на основе банковских выписок и данных учётной системы.', TIMESTAMP '2026-03-25 09:30:00', DATE '2026-04-13', DATE '2026-11-30'),
