INSERT INTO tasks (task_id, project_id, title, description, created_by, assignee_id, status, priority, created_at, due_date, completed_at)
OVERRIDING SYSTEM VALUE
VALUES
    (1, 1, 'Согласовать структуру карточки клиента', 'Утвердить обязательные поля: контактное лицо, телефон, организация, адрес аптеки и история обращений.', 1, 21, 'completed', 'high', TIMESTAMP '2025-11-04 10:00:00', DATE '2025-11-12', TIMESTAMP '2025-11-10 12:00:00'),
    (2, 1, 'Очистить список аптечных точек', 'Найти дубли организаций, проверить адреса и привести телефоны к единому формату перед импортом.', 11, 22, 'in_progress', 'medium', TIMESTAMP '2025-11-10 11:00:00', DATE '2025-11-19', NULL),
    (3, 1, 'Настроить права сотрудников аптек', 'Разделить доступ фармацевтов, операторов контактного центра и региональных руководителей.', 21, 23, 'new', 'low', TIMESTAMP '2025-11-16 12:00:00', DATE '2025-11-26', NULL),
    (4, 1, 'Перенести историю обращений', NULL, 11, 21, 'in_progress', 'medium', TIMESTAMP '2025-11-22 13:00:00', DATE '2025-12-03', NULL),
    (5, 1, 'Подготовить инструкцию для операторов', 'Описать регистрацию клиента, поиск существующей карточки и фиксацию результата звонка.', 1, NULL, 'cancelled', 'high', TIMESTAMP '2025-11-28 09:00:00', DATE '2025-12-10', NULL),
    (6, 2, 'Согласовать состав мобильного каталога', 'Определить категории, отображение остатков, цены по карте лояльности и недоступные позиции.', 2, 24, 'completed', 'high', TIMESTAMP '2025-12-03 10:00:00', DATE '2025-12-16', TIMESTAMP '2025-12-09 12:00:00'),
    (7, 2, 'Подключить оплату банковской картой', 'Настроить тестовый платёжный сценарий, обработку отказа банка и возврат средств.', 12, 25, 'in_progress', 'medium', TIMESTAMP '2025-12-09 11:00:00', DATE '2025-12-23', NULL),
    (8, 2, 'Реализовать статусы доставки', 'Отображать сборку заказа, передачу курьеру, выезд и фактическое вручение покупателю.', 24, 26, 'new', 'low', TIMESTAMP '2025-12-15 12:00:00', NULL, NULL),
    (9, 2, 'Добавить повтор предыдущего заказа', 'Перенести состав прошлой покупки в корзину и предупредить об отсутствующих товарах.', 12, 24, 'completed', 'medium', TIMESTAMP '2025-12-21 13:00:00', DATE '2025-12-28', TIMESTAMP '2025-12-27 15:00:00'),
    (10, 2, 'Подготовить сборку для приёмочного тестирования', 'Собрать Android-версию приложения и передать тестировщикам перечень изменений.', 2, 25, 'in_progress', 'high', TIMESTAMP '2025-12-27 09:00:00', DATE '2026-01-04', NULL),
    (11, 3, 'Описать витрину розничных продаж', NULL, 3, 27, 'new', 'high', TIMESTAMP '2026-01-12 10:00:00', DATE '2026-01-21', NULL),
    (12, 3, 'Настроить ежедневную загрузку чеков', 'Забирать закрытые чеки из кассовой системы и сохранять протокол отклонённых записей.', 13, 28, 'completed', 'medium', TIMESTAMP '2026-01-18 11:00:00', DATE '2026-01-28', TIMESTAMP '2026-01-24 13:00:00'),
    (13, 3, 'Сверить выручку с учётной системой', 'Сравнить дневные итоги по магазинам с контрольным отчётом ERP за три месяца.', 27, 29, 'in_progress', 'low', TIMESTAMP '2026-01-24 12:00:00', DATE '2026-02-04', NULL),
    (14, 3, 'Добавить разрез по регионам', 'Добавить фильтр по региону, городу и торговой точке в отчёт о динамике продаж.', 13, 27, 'cancelled', 'medium', TIMESTAMP '2026-01-30 13:00:00', DATE '2026-02-11', NULL),
    (15, 3, 'Оптимизировать расчёт валовой маржи', 'Проверить формулу маржи с учётом скидок и ускорить построение квартального отчёта.', 3, 28, 'in_progress', 'high', TIMESTAMP '2026-02-05 09:00:00', NULL, NULL),
    (16, 4, 'Спроектировать раздел договоров', 'Определить состав реквизитов договора, список приложений и правила отображения архивных документов.', 4, 30, 'completed', 'high', TIMESTAMP '2026-01-27 10:00:00', DATE '2026-02-10', TIMESTAMP '2026-02-02 12:00:00'),
    (17, 4, 'Реализовать восстановление доступа', 'Добавить подтверждение по корпоративной почте и ограничить срок действия ссылки восстановления.', 14, NULL, 'new', 'medium', TIMESTAMP '2026-02-02 11:00:00', DATE '2026-02-17', NULL),
    (18, 4, 'Добавить выгрузку закрывающих документов', 'Подготовить скачивание актов и счетов в PDF за выбранный расчётный период.', 30, 24, 'in_progress', 'low', TIMESTAMP '2026-02-08 12:00:00', DATE '2026-02-15', NULL),
    (19, 4, 'Проверить разграничение доступа организаций', NULL, 14, 30, 'completed', 'medium', TIMESTAMP '2026-02-14 13:00:00', DATE '2026-02-22', TIMESTAMP '2026-02-20 15:00:00'),
    (20, 4, 'Согласовать тексты уведомлений', 'Подготовить сообщения о новых актах, изменении статуса договора и сроках оплаты.', 4, 21, 'new', 'high', TIMESTAMP '2026-02-20 09:00:00', DATE '2026-03-01', NULL),
    (21, 5, 'Описать процесс приёмки поставки', 'Зафиксировать проверку количества мест, сроков годности и расхождений с накладной поставщика.', 5, 22, 'in_progress', 'high', TIMESTAMP '2026-02-04 10:00:00', DATE '2026-02-14', NULL),
    (22, 5, 'Сверить справочник складов', 'Проверить коды, адреса и режимы работы центрального склада и региональных площадок.', 15, 25, 'cancelled', 'medium', TIMESTAMP '2026-02-10 11:00:00', NULL, NULL),
    (23, 5, 'Подготовить модель складских остатков', 'Определить хранение остатков по складу, товару, партии и сроку годности.', 22, 28, 'completed', 'low', TIMESTAMP '2026-02-16 12:00:00', DATE '2026-02-28', TIMESTAMP '2026-02-22 14:00:00'),
    (24, 5, 'Настроить оформление инвентаризации', 'Описать регистрацию излишков и недостач с обязательным указанием причины корректировки.', 15, 22, 'in_progress', 'medium', TIMESTAMP '2026-02-22 13:00:00', DATE '2026-03-07', NULL),
    (25, 5, 'Оценить обмен с WMS', 'Сравнить пакетную загрузку и обмен событиями для синхронизации складских операций.', 5, 25, 'new', 'high', TIMESTAMP '2026-02-28 09:00:00', DATE '2026-03-14', NULL),
    (26, 6, 'Провести аудит каталога товаров', 'Найти дубли категорий, карточки без изображений и товары с неполными характеристиками.', 6, 23, 'completed', 'high', TIMESTAMP '2026-02-16 10:00:00', DATE '2026-03-03', TIMESTAMP '2026-02-22 12:00:00'),
